const $=s=>document.querySelector(s),status=$('#status');let view='bookings',data={bookings:[],clients:[],work:[]};
async function api(path,body,method=body?'POST':'GET'){const r=await fetch('/api/'+path,{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const value=await r.json();if(!r.ok){if(r.status===401){$('#workspace').hidden=true;$('#login').hidden=false;}throw new Error(value.error||'Please try again.');}return value;}
function node(tag,text){const e=document.createElement(tag);e.textContent=text;return e;}
function action(label,run){const b=node('button',label);b.className='button';b.onclick=async()=>{b.disabled=true;try{await run();await load();}catch(e){status.textContent=e.message;}finally{b.disabled=false;}};return b;}
function render(){const list=$('#records');list.replaceChildren();const query=$('#search').value.toLowerCase();const rows=data[view].filter(row=>JSON.stringify(row).toLowerCase().includes(query));for(const row of rows){const card=node('article','');card.className='record';if(view==='bookings'){card.append(node('h3',row.customer_name),node('p',`${row.service_name} · ${new Date(row.preferred_at).toLocaleString('en-NG',{timeZone:'Africa/Lagos'})} (Lagos)\n${row.status} · ${row.paid_at?'Payment received':'Awaiting payment'} · Due ₦${(row.amount_due/100).toLocaleString()}\n${row.phone} · ${row.email}\n${row.notes}`),node('small',row.payment_reference));const a=node('a','WhatsApp ↗');a.className='button';a.href=`https://wa.me/${row.phone}?text=${encodeURIComponent(`Hi ${row.customer_name}, this is 23 Lux Nails about your ${row.service_name} booking.`)}`;a.target='_blank';a.rel='noopener';card.append(a);if(['confirmed','awaiting_payment'].includes(row.status))for(const state of ['completed','cancelled'])card.append(action(state,()=>api('owner/bookings',{id:row.id,status:state},'PATCH')));}
 if(view==='clients'){card.append(node('h3',row.name),node('p',row.phone+' · '+row.email));const notes=node('textarea',row.notes);notes.maxLength=2000;notes.setAttribute('aria-label','Client notes');notes.placeholder='Visit preferences and service notes. Avoid sensitive health information.';card.append(notes,action('Save notes',()=>api('owner/clients',{id:row.id,notes:notes.value},'PATCH')));for(const booking of data.bookings.filter(b=>b.client_id===row.id))card.append(node('p',`${booking.service_name} · ${new Date(booking.preferred_at).toLocaleDateString('en-NG',{timeZone:'Africa/Lagos'})} · ${booking.status}`));for(const work of data.work.filter(w=>w.client_id===row.id)){const img=node('img','');img.src=work.url;img.alt=work.caption;card.append(img,node('p',work.caption));}}
 if(view==='work'){const image=node('img','');image.src=row.url;image.alt=row.caption;card.append(image,node('h3',row.caption),node('p',`${data.clients.find(c=>c.id===row.client_id)?.name||'Client'} · ${row.published?'Public':'Private'}`));const label=node('label','Client consents to public use '),check=node('input','');check.type='checkbox';check.checked=row.public_consent;label.className='check';label.prepend(check);card.append(label,action(row.published?'Hide from website':'Publish on website',()=>api('owner/work',{id:row.id,published:!row.published,consent:check.checked},'PATCH')));}
 list.append(card);}if(!rows.length)list.append(node('p','No matching records.'));}
function appointments(){const selected=$('#appointment').value;$('#appointment').replaceChildren(new Option('No appointment selected',''),...data.bookings.filter(b=>b.client_id===$('#client').value).map(b=>new Option(b.service_name+' · '+new Date(b.preferred_at).toLocaleDateString(),b.id)));if([...$('#appointment').options].some(o=>o.value===selected))$('#appointment').value=selected;}
async function load(){status.textContent='Loading studio records…';[data.bookings,data.clients,data.work]=await Promise.all(['bookings','clients','work'].map(name=>api('owner/'+name)));const client=$('#client').value;$('#client').replaceChildren(...data.clients.map(c=>new Option(c.name+' · '+c.phone,c.id)));if(data.clients.some(c=>c.id===client))$('#client').value=client;appointments();render();status.textContent='Records loaded. Showing up to 200 bookings/photos and 500 clients. Refresh to get new bookings. Status changes do not send a message or refund a payment.';}
$('#login').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{const f=new FormData(e.currentTarget);await api('login',Object.fromEntries(f));e.target.reset();$('#login').hidden=true;$('#workspace').hidden=false;await load();}catch(e){status.textContent=e.message;}finally{button.disabled=false;}};
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();});$('#search').oninput=render;$('#refresh').onclick=()=>load().catch(e=>status.textContent=e.message);$('#client').onchange=appointments;$('#logout').onclick=async()=>{try{await api('logout',{});location.reload();}catch(e){status.textContent=e.message;}};
$('#upload').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const file=$('#photo').files[0];if(file.size>5242880)throw new Error('Use a photo under 5 MB.');const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('owner/work',{clientId:$('#client').value,bookingId:$('#appointment').value,caption:$('#caption').value,category:$('#category').value,consent:$('#consent').checked,image});e.target.reset();await load();view='work';render();}catch(e){status.textContent=e.message;}finally{button.disabled=false;}};
